static void cleanup_domain ( struct protection_domain * domain ) { struct iommu_dev_data * entry ; unsigned long flags ; spin_lock_irqsave ( & domain -> lock , flags ) ; while ( ! list_empty ( & domain -> dev_list ) ) { entry = list_first_entry ( & domain -> dev_list , iommu_dev_data , list ) ; BUG_ON ( ! entry -> domain ) ; do_detach ( entry , NULL ) ; } spin_unlock_irqrestore ( & domain -> lock , flags ) ; } 